/**
 * Demo history: synthetic landmark sessions of a recovering left-sided palsy,
 * pushed through the real analysis pipeline. Clearly marked mode: 'demo'.
 * Per-muscle detail comes from the synthetic expressions there are (no tight eye
 * closure or lower-lip depression: those items stay empty); the last sessions
 * carry a linked synkinesis record once synkinesis sets in.
 */
import { analyzeCoupling, analyzeMuscles, analyzeSession } from '../core';
import { rng, syntheticSession } from '../core/synthetic';
import { localDate, uid } from './db';
import { createSessionRecord, createSynkRecord } from './records';
import { CONSENT_VERSION } from './consent';
import type { Profile, RehabLog, SessionRecord, SynkRecord } from './types';

const ONSET_DAYS_AGO = 112;
const SESSION_DAYS = [3, 10, 17, 26, 38, 52, 66, 81, 96, 110];

export async function buildDemo(): Promise<{ profile: Profile; sessions: SessionRecord[]; synk: SynkRecord[]; rehab: RehabLog[] }> {
  const now = new Date();
  const onset = new Date(now);
  onset.setDate(onset.getDate() - ONSET_DAYS_AGO);
  const profile: Profile = {
    id: uid(),
    createdAt: onset.toISOString(),
    nickname: '데모 사용자',
    birthYear: 1978,
    affectedSide: 'left',
    onsetDate: localDate(onset),
    etiology: 'bell',
    consent: { version: CONSENT_VERSION, at: onset.toISOString(), researchExport: false },
    safetyScreenAt: onset.toISOString(),
    voiceGuide: true,
    viewMode: 'mirror',
    demo: true,
  };

  const sessions: SessionRecord[] = [];
  const synk: SynkRecord[] = [];
  for (const [i, d] of SESSION_DAYS.entries()) {
    const strength = 0.06 + 0.86 * (1 - Math.exp(-Math.max(0, d - 8) / 32));
    const subject = {
      affectedSide: 'left' as const,
      strength,
      // Eye closure tends to recover first, the forehead last.
      taskStrength: {
        brow: strength ** 1.8,
        eyeClose: Math.min(1, strength * 1.12),
        smile: strength ** 1.15,
        snarl: strength,
        pucker: strength ** 0.9,
      },
      droop: Math.max(0, 0.95 - d / 55),
      synkinesis: d > 55 ? Math.min(0.55, (d - 55) / 90) : 0,
      drag: 1,
    };
    const r = rng(100 + i);
    const input = syntheticSession(subject, {
      seed: 100 + i,
      camera: { rollDeg: (r() - 0.5) * 6, ipdPx: 130 + r() * 40, noise: 0.0025 },
    });
    const analysis = analyzeSession({ ...input, mode: 'video' });
    const t = input.tasks;
    const muscles = analyzeMuscles({
      affectedSide: 'left',
      rest: input.rest,
      expressions: { brow: t.brow, eyeGentle: t.eyeClose, smile: t.smile, snarl: t.snarl, pucker: t.pucker },
    });
    const at = new Date(onset);
    at.setDate(at.getDate() + d);
    at.setHours(9 + (i % 3) * 4, 12, 0, 0);
    const record = await createSessionRecord({ analysis, muscles, profile, mode: 'demo', engine: null, camera: null, at });
    sessions.push(record);
    if (subject.synkinesis > 0 && i >= SESSION_DAYS.length - 3) {
      const result = analyzeCoupling({
        affectedSide: 'left',
        rest: input.rest,
        expressions: { brow: t.brow, eyeGentle: t.eyeClose, smileClosed: t.smile, pucker: t.pucker },
      });
      if (result.status !== 'failed') synk.push(await createSynkRecord({ result, profile, engine: null, camera: null, sessionId: record.id, at }));
    }
  }

  const rehab: RehabLog[] = [];
  const r = rng(7);
  const ids = ['relax-breath', 'massage-eye', 'dissoc-smile-eye', 'zygomatic-lift', 'massage-cheek'];
  for (let back = 20; back >= 1; back--) {
    const day = new Date(now);
    day.setDate(day.getDate() - back);
    if (r() < 0.25) continue;
    for (const id of ids) {
      if (r() < 0.2) continue;
      rehab.push({ id: uid(), date: localDate(day), at: day.toISOString(), exerciseId: id, durationSec: 60 + Math.round(r() * 60) });
    }
  }
  return { profile, sessions, synk, rehab };
}
